<script setup lang="ts">
definePageMeta({middleware:'auth'});useSeoMeta({title:'职业图谱'})
const api=useApi();const jobsApi=useJobsApi();const toast=useToast();const options=ref<any[]>([]);const from=ref('');const to=ref('');const loading=ref(false);const promotion=ref<any>();const lateral=ref<any>();const transition=ref<any>();
async function loadOptions(){const data=await api.ok<any>('/api/jobs/options?page=1&page_size=100');options.value=data.jobs||[]}
async function analyze(){if(!from.value)return;loading.value=true;try{[promotion.value,lateral.value]=await Promise.all([jobsApi.promotion(from.value),jobsApi.lateral(from.value)]);if(to.value&&to.value!==from.value)transition.value=await jobsApi.transition(from.value,to.value)}catch(e){toast.add({title:String(e),color:'error'})}finally{loading.value=false}}
onMounted(loadOptions)
</script>
<template><div class="page-stack"><div class="page-heading"><h1>职业关联图谱</h1><p class="muted">查看岗位晋升路线、横向转岗与两岗差距</p></div><UCard><div class="grid gap-4 md:grid-cols-[1fr_1fr_auto]"><UFormField label="当前岗位"><USelectMenu v-model="from" value-key="id" label-key="title" :items="options" searchable class="w-full"/></UFormField><UFormField label="目标岗位（可选）"><USelectMenu v-model="to" value-key="id" label-key="title" :items="options" searchable class="w-full"/></UFormField><div class="flex items-end"><UButton :loading="loading" @click="analyze">分析路径</UButton></div></div></UCard><UEmpty v-if="!promotion&&!lateral" title="请选择岗位开始分析" icon="i-lucide-network"/><div v-else class="panel-grid two"><UCard><template #header><h2 class="text-lg font-semibold">晋升路径</h2></template><pre class="overflow-auto whitespace-pre-wrap text-sm">{{JSON.stringify(promotion,null,2)}}</pre></UCard><UCard><template #header><h2 class="text-lg font-semibold">横向转岗</h2></template><pre class="overflow-auto whitespace-pre-wrap text-sm">{{JSON.stringify(lateral,null,2)}}</pre></UCard><UCard v-if="transition" class="lg:col-span-2"><template #header><h2 class="text-lg font-semibold">目标差距与行动建议</h2></template><pre class="overflow-auto whitespace-pre-wrap text-sm">{{JSON.stringify(transition,null,2)}}</pre></UCard></div></div></template>
